/**
 * Binding-error callback — every wrapper's binding/system failure channel (any
 * converter in the chain may fail, or a handle may be closed). `je` is the
 * failure message. For an infallible wrapper this is the sole `onError`; a
 * fallible wrapper takes it as `onBindingError` alongside the typed domain
 * handler. The wrapper returns whatever `run` returns. Where that type is nullable you may
 * return `null` to decline — you are not required to fabricate a result. Consequently the
 * handler firing, not the returned value, is the error discriminator: `null` can also be a
 * successful optional result, and a non-null value can be a fallback you supplied. Throwing
 * from `run` is safe (it executes after the native call has returned).
 */
public fun interface JniErrorHandler<out R> {
    public fun run(je: String?): R
}

internal class JniErrorHandlerCapture : JniErrorHandler<Unit> {
    @JvmField var failed: Boolean = false
    @JvmField var ze0: String? = null
    override fun run(je: String?) { failed = true; this.ze0 = je }
    companion object {
        private val TL: ThreadLocal<JniErrorHandlerCapture> = ThreadLocal.withInitial { JniErrorHandlerCapture() }
        @JvmStatic fun acquire(): JniErrorHandlerCapture {
            val c = TL.get()
            c.failed = false; c.ze0 = null
            return c
        }
    }
}

/**
 * Deliver a present or absent handle-owning data class to a callback.
 *
 * The generated Kotlin bridge must close `token` after the callback unless
 * user code has already taken ownership of it.
 */
public fun callbackHolderOptionalEmit(
    present: Boolean,
    f: CallbackHolderOptionalCallback,
    onError: JniErrorHandler<Unit>,
) {
    val __bcap = JniErrorHandlerCapture.acquire()
    CovNative.callbackHolderOptionalEmit(present, f.asRaw(), __bcap)
    if (__bcap.failed) return onError.run(__bcap.ze0)
}

